<template>
  <div class="guidance-asset-field" :class="{ 'guidance-asset-field--filled': hasAsset, 'guidance-asset-field--video': mediaKind === 'video' }">
    <el-upload class="guidance-asset-field__upload" drag :show-file-list="false" :accept="accept" :http-request="upload" :before-upload="beforeUpload" :disabled="uploading">
      <template v-if="!hasAsset"><el-icon class="guidance-asset-field__icon"><component :is="mediaKind === 'video' ? VideoCamera : Picture" /></el-icon><div class="guidance-asset-field__title">{{ uploading ? '正在上传素材…' : uploadTitle }}</div><div class="guidance-asset-field__hint">{{ hint }}</div></template>
      <template v-else>
        <div class="guidance-asset-field__media" @click.stop>
          <video v-if="mediaKind === 'video'" :src="displayUrl" class="guidance-asset-field__preview" controls preload="metadata" @error="mediaFailed = true" />
          <img v-else :src="displayUrl" class="guidance-asset-field__preview" :alt="fileName" @error="mediaFailed = true" />
          <div v-if="mediaFailed" class="guidance-asset-field__failed">素材无法加载，请检查资源服务后重新上传</div>
        </div>
        <div class="guidance-asset-field__overlay"><span>点击替换</span></div>
      </template>
    </el-upload>
    <div v-if="hasAsset" class="guidance-asset-field__meta"><span><i class="guidance-asset-field__dot"></i>{{ fileName }}</span><div class="guidance-asset-field__actions"><el-button link type="primary" @click.stop="preview">预览</el-button><el-button link type="danger" @click="clear">移除</el-button></div></div><Teleport to="body"><div v-if="previewing" class="guidance-asset-preview-mask" @click.self="previewing=false"><section class="guidance-asset-preview-panel" role="dialog" aria-modal="true"><header><strong>{{ mediaKind === 'video' ? '视频预览' : '图片预览' }}</strong><button type="button" aria-label="关闭预览" @click="previewing=false">×</button></header><div class="guidance-asset-preview-panel__body"><video v-if="mediaKind === 'video'" :src="displayUrl" controls autoplay></video><img v-else :src="displayUrl" :alt="fileName"/></div></section></div></Teleport>
  </div>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ElMessage } from 'element-plus';
import { Picture, VideoCamera } from '@element-plus/icons-vue';
import type { UploadRequestOptions } from 'element-plus';
import type { GuidanceAssetDto } from '@home-rehab-motion/shared-contract';
import { presignUpload } from '@/services/guidance';
import http from '@/utils/request';
const props = withDefaults(defineProps<{ modelValue?: GuidanceAssetDto; mediaKind?: 'image' | 'video'; uploadTitle?: string }>(), { modelValue: () => ({ url: '' }), mediaKind: 'image', uploadTitle: '点击或拖拽上传素材' });
const emit = defineEmits<{ (event: 'update:modelValue', value: GuidanceAssetDto): void }>();
const uploading = ref(false); const mediaFailed = ref(false); const previewing = ref(false);
const hasAsset = computed(() => Boolean(props.modelValue?.url));
const displayUrl = computed(() => normalizeAssetUrl(props.modelValue?.url));
const accept = computed(() => props.mediaKind === 'video' ? 'video/mp4,video/quicktime,video/x-m4v' : 'image/png,image/jpeg,image/gif,image/webp');
const hint = computed(() => props.mediaKind === 'video' ? '支持 MP4 / MOV，最大 200MB' : '支持 JPG / PNG / GIF / WebP，最大 20MB');
const fileName = computed(() => props.modelValue?.objectKey?.split('/').pop() || props.modelValue?.url.split('/').pop() || '已上传素材');
watch(() => props.modelValue?.url, () => { mediaFailed.value = false; });
function normalizeAssetUrl(url?: string) { if (!url || /^https?:\/\//.test(url) || url.startsWith('data:') || url.startsWith('blob:')) return url || ''; return url.startsWith('/') ? url : `/${url}`; }
function beforeUpload(file: File) { const isVideo = props.mediaKind === 'video'; if ((isVideo && !file.type.startsWith('video/')) || (!isVideo && !file.type.startsWith('image/'))) { ElMessage.error(isVideo ? '请上传视频文件' : '请上传图片或 GIF 文件'); return false; } const limit = isVideo ? 200 * 1024 * 1024 : 20 * 1024 * 1024; if (file.size > limit) { ElMessage.error(isVideo ? '教学视频不能超过 200MB' : '图片或 GIF 不能超过 20MB'); return false; } return true; }
async function upload(options: UploadRequestOptions) { const file = options.file as File; uploading.value = true; mediaFailed.value = false; try { const target = await presignUpload(file.name, props.mediaKind, file.type); if (target.uploadType === 's3_post') { const data = new FormData(); Object.entries(target.uploadFields || {}).forEach(([key, value]) => data.append(key, value)); data.append('file', file); const response = await fetch(target.uploadUrl, { method: 'POST', body: data }); if (!response.ok) throw new Error('对象存储上传失败'); } else { const data = new FormData(); data.append('objectKey', target.objectKey); data.append('file', file); await http.post(target.uploadUrl, data, { headers: { 'Content-Type': 'multipart/form-data' } }); } const previewUrl = target.uploadType === 's3_post' ? URL.createObjectURL(file) : normalizeAssetUrl(target.assetUrl); emit('update:modelValue', { objectKey: target.objectKey, url: previewUrl, mimeType: file.type, sizeBytes: file.size }); ElMessage.success(`${props.mediaKind === 'video' ? '视频' : '图片'}上传成功，已同步到右侧预览`); options.onSuccess?.({}); } catch (error: any) { ElMessage.error(error?.response?.data?.message || error?.message || '素材上传失败'); options.onError?.(error); } finally { uploading.value = false; } }
function preview() { previewing.value = true; } function clear() { mediaFailed.value = false; emit('update:modelValue', { url: '' }); }
</script>
<style>
.guidance-asset-field{min-width:0}.guidance-asset-field__upload :deep(.el-upload),.guidance-asset-field__upload :deep(.el-upload-dragger){width:100%;height:158px;border-radius:14px}.guidance-asset-field--video{max-width:900px}.guidance-asset-field--video .guidance-asset-field__upload :deep(.el-upload),.guidance-asset-field--video .guidance-asset-field__upload :deep(.el-upload-dragger){height:210px;aspect-ratio:auto;border-radius:16px}.guidance-asset-field--video .guidance-asset-field__preview{object-fit:contain}.guidance-asset-field--video .guidance-asset-field__media{background:#0e2536}.guidance-asset-field__upload :deep(.el-upload-dragger){position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:center;align-items:center;border:1px dashed #a9c8d8;background:#f8fbfd}.guidance-asset-field__upload:hover :deep(.el-upload-dragger){border-color:#16827d;background:#f0fbfb}.guidance-asset-field__icon{font-size:29px;color:#16827d}.guidance-asset-field__title{margin-top:8px;color:#243b53;font-size:13px;font-weight:800}.guidance-asset-field__hint{margin-top:4px;color:#748aa0;font-size:12px}.guidance-asset-field__media{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:#18384e}.guidance-asset-field__preview{width:100%;height:100%;object-fit:contain}.guidance-asset-field__overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(12,43,61,.52);opacity:0;color:#fff;font-size:13px;font-weight:700;transition:opacity .2s}.guidance-asset-field__upload:hover .guidance-asset-field__overlay{opacity:1}.guidance-asset-field__failed{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(20,45,59,.82);color:#fff;font-size:12px;line-height:1.6;text-align:center}.guidance-asset-field__meta{display:flex;justify-content:space-between;gap:12px;padding:9px 2px 0;color:#637b91;font-size:12px}.guidance-asset-field__meta span{display:flex;align-items:center;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.guidance-asset-field__actions{display:flex;flex:0 0 auto;gap:8px}.guidance-asset-field__dot{width:7px;height:7px;flex:0 0 auto;margin-right:7px;border-radius:50%;background:#33a276}.guidance-asset-preview-mask{position:fixed;inset:0;z-index:2147483647;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(5,18,29,.72);box-sizing:border-box}.guidance-asset-preview-panel{width:min(1080px,94vw);max-height:calc(100vh - 48px);overflow:hidden;border:1px solid rgba(164,214,220,.28);border-radius:16px;background:#102e40;box-shadow:0 28px 72px rgba(0,0,0,.56)}.guidance-asset-preview-panel header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid rgba(164,214,220,.18);color:#e5fbfa}.guidance-asset-preview-panel header button{width:30px;height:30px;padding:0;border:0;border-radius:50%;background:rgba(255,255,255,.12);color:#e5fbfa;font-size:24px;line-height:1;cursor:pointer}.guidance-asset-preview-panel__body{display:flex;align-items:center;justify-content:center;min-height:280px;padding:4px;background:#102e40}.guidance-asset-preview-panel__body video,.guidance-asset-preview-panel__body img{display:block;width:auto;max-width:100%;max-height:78vh;margin:auto;object-fit:contain;background:#102e40}
</style>
